<script setup lang="ts">
import AnalysisProgress from './AnalysisProgress.vue';
import UButton from '@nuxt/ui/components/Button.vue';
import { computed, ref,watch } from 'vue';
import type { LiveMonitorReport } from '@/api/smartbi/blacklake-live';
const props = defineProps<{ report: LiveMonitorReport | null }>();
const emit = defineEmits<{ (event: 'refresh'): void; (event: 'history-page', offset: number): void; (event: 'open-report', reportId: string): void }>();
const date = (value: string | null | undefined) => value ? new Date(value).toLocaleString('zh-CN', { timeZone:'Asia/Shanghai',month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', hour12: false }) : '未提供';
const count = (value: number | undefined) => value == null ? '未提供' : value.toLocaleString('zh-CN');
const statusText = (status: string) => ({ pending_latest:'最新数据待复核',running: '处理中', success: '成功', queued: '排队中', ready: '已保存', stale: '已中断', completed: '观察期已结束', failed: '失败', waiting: '等待中' }[status] || status || '未提供');
const countKeys = ['project', 'task', 'output', 'stock_order', 'product', 'process', 'routing', 'unit', 'warehouse', 'materials', 'bom', 'project_expand', 'stock'];
const countLabels: Record<string, string> = { project: '工单', task: '工序任务', output: '报工', stock_order: '出入库单', product: '产品定义', process: '工序定义', routing: '工艺路线', unit: '计量单位', warehouse: '仓库', materials: '工单用料参考', bom: '配方参考', project_expand: '工序展开参考', stock: '库存余额' };
const page = ref(1);
const pageCount = computed(() => Math.max(1, Math.ceil((props.report?.history.length || 0) / 20)));
const visibleHistory = computed(() => props.report?.history.slice((page.value - 1) * 20, page.value * 20) || []);
watch(()=>props.report?.historyOffset,()=>{page.value=1;});
watch(pageCount,count=>{page.value=Math.min(page.value,count);});
const analysisText=computed(()=>({ready:'已保存分析结果，可以查看问题和处理建议。',pending_latest:'有新数据，正在等候复核。',running:'正在整理分析，数据可以先看。',queued:'分析正在排队，完成后会自动保存。',failed:'本次分析暂未完成，原始数据已保留。'}[props.report?.analysis.status||'']||props.report?.analysis.message||'等待采集数据。'));
</script>
<template>
  <section class="live-monitor" aria-label="自动更新记录">
    <header class="monitor-heading"><div><h2>自动更新记录</h2><p v-if="props.report">每 {{ props.report.intervalSeconds }} 秒拉取数据，有变化时排队复核。</p></div><UButton color="neutral" variant="outline" size="sm" @click="emit('refresh')">刷新状态</UButton></header>
    <div v-if="!props.report" class="empty">暂无监视数据。</div>
    <template v-else>
      <div class="facts"><div><b>最近成功更新</b><strong>{{ date(props.report.lastSuccessAt) }}</strong></div><div><b>本次观察已成功</b><strong>{{ count(props.report.successfulCycles) }} 次</strong></div><div><b>下次更新</b><strong>{{ props.report.enabled ? date(props.report.nextRunAt) : '观察期已结束' }}</strong></div></div>
      <p v-if="props.report.error" class="error">最近失败：{{ props.report.error }}</p>
      <div class="analysis"><div><b>分析报告</b><p>{{analysisText}}</p></div><UButton v-if="props.report.analysis.reportId" color="primary" class="report-link" @click="emit('open-report',props.report.analysis.reportId)">查看问题与处理建议</UButton></div>
      <AnalysisProgress :progress="props.report.analysis.progress" :status="props.report.analysis.status" :stage="props.report.analysis.stage" />
      <p class="period-note">观察期 {{date(props.report.startedAt)}} 至 {{date(props.report.endsAt)}}</p>
      <details class="history"><summary>查看更新记录和模型用量</summary><p class="period-note">共尝试 {{props.report.cycles}} 次；本份报告用量 {{props.report.analysis.tokens==null?'未返回':count(props.report.analysis.tokens)+' tokens'}}。</p><div v-if="!props.report.history.length" class="empty small">暂无历史轮次。</div><template v-else><table><thead><tr><th>开始</th><th>完成</th><th>结果</th><th>数据变化</th><th>采集资料</th><th>报告</th></tr></thead><tbody><tr v-for="cycle in visibleHistory" :key="cycle.id"><td>{{date(cycle.startedAt)}}</td><td>{{date(cycle.finishedAt)}}</td><td>{{statusText(cycle.status)}}<p v-if="cycle.error" class="row-error">{{cycle.error}}</p></td><td>{{cycle.changed?'有变化':'无变化'}}</td><td><details><summary>工单 {{cycle.counts.project??'—'}} · 报工 {{cycle.counts.output??'—'}} · 库存 {{cycle.counts.stock??'—'}}</summary><p>{{countKeys.filter(key=>(cycle.counts[key]??cycle.totals?.[key])!=null).map(key=>`${countLabels[key]} ${cycle.counts[key]??cycle.totals?.[key]}`).join('、')}}</p><p>只读请求 {{count(cycle.requests)}} 次</p></details></td><td><button v-if="cycle.analysisReportId" type="button" class="report-link" @click="emit('open-report',cycle.analysisReportId)">查看</button><span v-else>等待关联</span></td></tr></tbody></table><div v-if="pageCount>1" class="pager"><button type="button" :disabled="page===1" @click="page--">上一页</button><span>第 {{page}} / {{pageCount}} 页</span><button type="button" :disabled="page===pageCount" @click="page++">下一页</button></div><div v-if="props.report.historyOffset||props.report.historyHasMore" class="server-pager"><button type="button" :disabled="(props.report.historyOffset||0)<100" @click="emit('history-page',Math.max(0,(props.report.historyOffset||0)-100))">较新记录</button><button type="button" :disabled="!props.report.historyHasMore" @click="emit('history-page',(props.report.historyOffset||0)+100)">更早记录</button></div></template></details>
    </template>
  </section>
</template>
<style scoped>
.analysis>.report-link{background:var(--c-primary,#1b65a8);color:white;padding:9px 14px;border-radius:6px;white-space:nowrap;font-weight:600}
.facts strong{display:block;font-size:19px;line-height:1.4;color:var(--c-ink,#26384d);font-weight:600}.analysis{display:flex;justify-content:space-between;align-items:center;gap:18px!important;padding:16px!important;margin:16px 0!important}.analysis p{margin:6px 0 0}.period-note{font-size:12px;color:var(--c-muted,#738196);line-height:1.7}.history>summary{cursor:pointer;color:var(--c-primary,#1b65a8);padding:8px 0}.history table details summary{font-size:12px;cursor:pointer}.history td{vertical-align:top}.server-pager{display:flex;gap:10px;justify-content:flex-end;margin-top:12px}.server-pager button{padding:6px 10px;border:1px solid var(--c-line,#e5eaf0);border-radius:5px}@media(max-width:760px){.analysis{align-items:flex-start;flex-direction:column}}
.report-link{border:0;background:transparent;color:#1b65a8;cursor:pointer;padding:0}
.live-monitor{padding:20px;border:1px solid var(--c-line,#e5eaf0);border-radius:12px;background:var(--c-surface,#fff);color:var(--c-ink,#1a2332)}.monitor-heading{display:flex;justify-content:space-between;gap:16px;align-items:flex-start}.monitor-heading h2{font-size:18px;margin:0 0 6px}.monitor-heading p,.window,.facts,.analysis,.error{font-size:13px;line-height:1.65;color:#526276}.window{display:flex;flex-wrap:wrap;gap:10px 18px;margin:18px 0;padding:12px;background:#f7f9fb;border-radius:8px}.window b{color:#334458}.window em{font-style:normal;color:#95620e}.facts{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px}.facts div{padding:11px;border:1px solid #edf1f5;border-radius:7px}.facts b,.analysis b{display:block;font-size:11px;color:#66758a;margin-bottom:3px}.error{padding:10px;color:#9b3d38;background:#fff0ef;border-radius:7px}.analysis{margin:14px 0;padding:10px;background:#f7f9fb;border-radius:7px}.analysis b{display:inline;margin-right:8px}.history h3{font-size:14px;margin:18px 0 8px}.history table{width:100%;border-collapse:collapse;font-size:13px}.history th,.history td{text-align:left;padding:9px 7px;border-bottom:1px solid #edf1f5;font-weight:400}.history th{font-size:12px;color:#66758a}.row-error{color:#9b3d38}.empty{text-align:center;padding:28px 0;color:#738196;font-size:13px}.empty.small{padding:15px 0}.pager{display:flex;align-items:center;gap:12px;justify-content:flex-end;margin-top:10px;font-size:12px;color:#66758a}.pager button{border:1px solid #dce3ec;border-radius:5px;background:#fff;padding:5px 9px;cursor:pointer;color:#345c91}.pager button:disabled{cursor:not-allowed;color:#aab3bf}@media(max-width:760px){.facts{grid-template-columns:1fr 1fr}.history{overflow:auto}.history table{min-width:650px}}
</style>
